"""The shared sample corpus: a small, stable canonical JSONL snapshot both developers build on
before real ingestion lands (plan section 4, "parallel work rules").

The committed file ``tests/fixtures/data/sample_tools.jsonl`` is generated by this module and
checked by ``tests/test_fixtures.py``. Regenerate after an intentional change with::

    uv run python -m tests.fixtures.sample_corpus
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from mcpgw.contracts.records import ToolRecord, write_snapshot

SAMPLE_PATH = Path(__file__).parent / "data" / "sample_tools.jsonl"


def _s(props: dict[str, Any], required: list[str]) -> dict[str, Any]:
    return {"type": "object", "properties": props, "required": required}


_STR = {"type": "string"}

# (alias, name, description, input schema, annotations). Deliberately includes near-duplicates
# across servers (fs__read_file / git__show_file; two "search" tools) for retrieval tests.
_TOOLS: list[tuple[str, str, str, dict[str, Any], dict[str, Any] | None]] = [
    (
        "fs",
        "read_file",
        "Read the complete contents of a file as text.",
        _s({"path": {**_STR, "description": "Absolute path of the file"}}, ["path"]),
        {"readOnlyHint": True},
    ),
    (
        "fs",
        "write_file",
        "Create or overwrite a file with the given content.",
        _s({"path": _STR, "content": _STR}, ["path", "content"]),
        {"destructiveHint": True},
    ),
    (
        "fs",
        "list_directory",
        "List files and folders in a directory.",
        _s({"path": _STR}, ["path"]),
        {"readOnlyHint": True},
    ),
    (
        "fs",
        "search_files",
        "Recursively search for files whose names match a pattern.",
        _s({"path": _STR, "pattern": _STR}, ["path", "pattern"]),
        {"readOnlyHint": True},
    ),
    (
        "git",
        "show_file",
        "Show a file's contents at a given revision.",
        _s({"path": _STR, "rev": {**_STR, "description": "Commit, branch or tag"}}, ["path"]),
        {"readOnlyHint": True},
    ),
    (
        "git",
        "diff",
        "Show changes between two revisions, optionally for one path.",
        _s({"from_rev": _STR, "to_rev": _STR, "path": _STR}, ["from_rev"]),
        {"readOnlyHint": True},
    ),
    (
        "git",
        "log",
        "List recent commits with author, date and message.",
        _s({"max_count": {"type": "integer"}, "path": _STR}, []),
        {"readOnlyHint": True},
    ),
    (
        "git",
        "commit",
        "Record staged changes with a commit message.",
        _s({"message": _STR}, ["message"]),
        None,
    ),
    (
        "web",
        "search",
        "Search the web and return the top results with titles and URLs.",
        _s({"query": _STR, "limit": {"type": "integer"}}, ["query"]),
        {"openWorldHint": True},
    ),
    (
        "web",
        "fetch_page",
        "Download a web page and convert it to Markdown.",
        _s(
            {
                "url": {**_STR, "format": "uri"},
                "options": _s({"max_length": {"type": "integer"}, "raw": {"type": "boolean"}}, []),
            },
            ["url"],
        ),
        {"openWorldHint": True},
    ),
    (
        "docs",
        "search",
        "Find relevant documents in the team knowledge base.",
        _s({"query": _STR}, ["query"]),
        {"readOnlyHint": True},
    ),
    ("docs", "get_document", "", _s({"id": _STR}, ["id"]), None),  # no_description on purpose
]


def build_sample_records() -> list[ToolRecord]:
    records = []
    for alias, name, desc, schema, hints in _TOOLS:
        flags = [] if desc else ["no_description"]
        records.append(
            ToolRecord.model_validate(
                {
                    "alias": alias,
                    "name": name,
                    "description": desc,
                    "inputSchema": schema,
                    "annotations": hints,
                    "flags": flags,
                }
            )
        )
    return records


def write_sample(path: Path = SAMPLE_PATH) -> dict[str, Any]:
    path.parent.mkdir(parents=True, exist_ok=True)
    return write_snapshot(build_sample_records(), path)


if __name__ == "__main__":
    print(write_sample())
